import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Card, CardContent, CardFooter, CardHeader } from "@/components/ui/card"
import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog"
import { createGoogleMapViewport, downloadGoogleMapSvg, type GoogleMapAddress, type GoogleMapViewport } from "@/lib/google-map-viewport"

function errorMessage(failure: unknown, fallback: string): string {
  // Errors from html2canvas in the child window have a different prototype.
  if (failure && typeof failure === "object" && "message" in failure && typeof failure.message === "string") return failure.message
  return fallback
}

type Session = { abort: AbortController; viewport?: GoogleMapViewport; busy: boolean }

export function GoogleMapDrawDialog({ open, onOpenChange }: { open: boolean; onOpenChange: (open: boolean) => void }) {
  const [iframe, setIframe] = useState<HTMLIFrameElement | null>(null)
  const [initialized, setInitialized] = useState(false)
  const [ready, setReady] = useState(false)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [address, setAddress] = useState("")
  const [results, setResults] = useState<GoogleMapAddress[]>([])
  const [searching, setSearching] = useState(false)
  const [searchError, setSearchError] = useState<string | null>(null)
  const [selectedResult, setSelectedResult] = useState(-1)
  const sessionRef = useRef<Session | null>(null)
  const searchGeneration = useRef(0)
  const selectedAddress = useRef("")
  const current = useCallback((session: Session) => sessionRef.current === session && !session.abort.signal.aborted, [])
  const retire = useCallback(() => {
    const session = sessionRef.current
    sessionRef.current = null
    searchGeneration.current++
    session?.abort.abort()
    session?.viewport?.dispose()
  }, [])
  const close = useCallback(() => { retire(); onOpenChange(false) }, [retire, onOpenChange])
  const closeRef = useRef(close)
  useLayoutEffect(() => { closeRef.current = close }, [close])
  useLayoutEffect(() => {
    if (!open) retire()
    return () => retire()
  }, [open, retire])

  useEffect(() => {
    if (!open || !iframe) return
    const session: Session = { abort: new AbortController(), busy: false }
    sessionRef.current = session
    setInitialized(false); setReady(false); setBusy(false); setError(null)
    setAddress(""); setResults([]); setSearchError(null); setSearching(false); setSelectedResult(-1)
    selectedAddress.current = ""
    void createGoogleMapViewport(iframe, {
      signal: session.abort.signal,
      onReady: (next) => { if (current(session)) setReady(next) },
      onError: (message) => { if (current(session)) { setReady(false); setError(message) } },
      onCloseRequest: () => { if (current(session)) closeRef.current() },
    }).then((viewport) => {
      if (!current(session)) { viewport.dispose(); return }
      session.viewport = viewport
      setInitialized(true)
    }).catch((failure) => {
      if (current(session)) { setReady(false); setError(errorMessage(failure, "The Google Map could not load.")) }
    })
    return () => {
      if (sessionRef.current === session) retire()
      else { session.abort.abort(); session.viewport?.dispose() }
    }
  }, [open, iframe, current, retire])

  useEffect(() => {
    const session = sessionRef.current
    const generation = ++searchGeneration.current
    setResults([]); setSearchError(null); setSearching(false); setSelectedResult(-1)
    const query = address.trim()
    if (!open || !initialized || !session?.viewport || query.length < 2 || query === selectedAddress.current) return
    const timer = setTimeout(() => {
      setSearching(true)
      void session.viewport!.search(query).then((addresses) => {
        if (!current(session) || searchGeneration.current !== generation) return
        setResults(addresses); setSearching(false)
        if (!addresses.length) setSearchError("No matching addresses found.")
      }).catch((failure) => {
        if (!current(session) || searchGeneration.current !== generation) return
        setSearching(false); setSearchError(errorMessage(failure, "Address search failed."))
      })
    }, 500)
    return () => clearTimeout(timer)
  }, [address, initialized, open, current])

  const select = (item: GoogleMapAddress) => {
    const session = sessionRef.current
    if (!session?.viewport || !current(session) || session.busy) return
    selectedAddress.current = item.formatted_address
    searchGeneration.current++
    setAddress(item.formatted_address); setResults([]); setSelectedResult(-1); setSearching(false); setSearchError(null)
    session.viewport.select(item)
  }
  const download = async () => {
    const session = sessionRef.current
    if (!initialized || !ready || !session?.viewport || session.busy || !current(session)) return
    session.busy = true
    setBusy(true); setError(null)
    try {
      const svg = await session.viewport.capture()
      if (current(session)) downloadGoogleMapSvg(svg)
    } catch (failure) {
      if (current(session)) setError(errorMessage(failure, "The SVG could not be downloaded."))
    } finally {
      if (current(session)) { session.busy = false; setBusy(false) }
    }
  }

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (!next) close()
      }}
    >
      <DialogContent
        data-slot="google-map-draw-dialog"
        showCloseButton={false}
        aria-describedby={undefined}
        onPointerDownOutside={(event) => event.preventDefault()}
        className="top-0 left-0 block h-dvh w-screen max-w-none translate-x-0 translate-y-0 overflow-hidden rounded-none border-0 p-0 shadow-none duration-0 data-[state=open]:animate-none data-[state=closed]:animate-none sm:max-w-none"
      >
        {open ? (
          <iframe
            ref={setIframe}
            title="Google Map viewport"
            inert={busy}
            className="absolute inset-0 h-full w-full border-0"
          />
        ) : null}
        <Card
          data-slot="google-map-draw-controls"
          className="absolute top-4 right-4 z-10 max-h-[calc(100dvh-2rem)] w-[360px] max-w-[calc(100%-2rem)] gap-3 overflow-y-auto overscroll-contain py-4"
          onWheel={(event) => event.stopPropagation()}
          onTouchMove={(event) => event.stopPropagation()}
        >
          <CardHeader className="px-4">
            <DialogTitle>Download overlay template</DialogTitle>
            <p className="text-sm text-muted-foreground">
              Enter an address, then zoom and pan the map to frame the area you need. Click Download,
              then open the SVG in a vector editor such as Inkscape or Adobe Illustrator.
            </p>
          </CardHeader>
          <CardContent className="space-y-2 px-4">
            <Input
              aria-label="Address"
              role="combobox"
              aria-autocomplete="list"
              aria-expanded={results.length > 0}
              aria-controls="mapsvg-google-address-results"
              aria-activedescendant={
                selectedResult >= 0 ? `mapsvg-google-address-${selectedResult}` : undefined
              }
              placeholder="Enter address…"
              value={address}
              disabled={!initialized || busy}
              onChange={(event) => {
                selectedAddress.current = ""
                setAddress(event.target.value)
              }}
              onKeyDown={(event) => {
                if (event.key === "ArrowDown" && results.length) {
                  event.preventDefault()
                  setSelectedResult((index) => (index + 1) % results.length)
                } else if (event.key === "ArrowUp" && results.length) {
                  event.preventDefault()
                  setSelectedResult((index) => (index + results.length - 1) % results.length)
                } else if (event.key === "Enter" && results.length) {
                  event.preventDefault()
                  select(results[Math.max(0, selectedResult)])
                } else if (event.key === "Escape" && results.length) {
                  event.preventDefault()
                  event.stopPropagation()
                  setResults([])
                }
              }}
            />
            {results.length ? (
              <ul
                id="mapsvg-google-address-results"
                role="listbox"
                aria-label="Matching addresses"
                className="max-h-64 overflow-y-auto overscroll-contain rounded-md border bg-popover p-1 shadow-md"
              >
                {results.map((item, index) => (
                  <li key={`${item.formatted_address}-${index}`}>
                    <button
                      type="button"
                      role="option"
                      disabled={busy}
                      id={`mapsvg-google-address-${index}`}
                      aria-selected={selectedResult === index}
                      className="w-full rounded-sm p-2 text-left text-sm hover:bg-accent focus:bg-accent"
                      onClick={() => select(item)}
                    >
                      {item.formatted_address}
                    </button>
                  </li>
                ))}
              </ul>
            ) : null}
            {searching ? (
              <p role="status" className="mt-2 text-xs text-muted-foreground">
                Searching addresses…
              </p>
            ) : null}
            {searchError ? (
              <p role="alert" className="mt-2 text-xs text-destructive">
                {searchError}
              </p>
            ) : null}
            {error ? (
              <p role="alert" className="text-sm text-destructive">
                {error}
              </p>
            ) : !initialized ? (
              <p role="status" className="text-sm text-muted-foreground">
                Loading Google Map…
              </p>
            ) : null}
          </CardContent>
          <CardFooter data-slot="google-map-draw-footer" className="justify-end gap-2 px-4">
            <Button type="button" variant="outline" onClick={close}>
              Close
            </Button>
            <Button
              type="button"
              disabled={!initialized || !ready || busy}
              onClick={() => void download()}
            >
              {busy ? "Downloading…" : "Download"}
            </Button>
          </CardFooter>
        </Card>
      </DialogContent>
    </Dialog>
  )
}
