import { getAdminParams } from "@/lib/admin-params"
import { loadGoogleMapsApiOnce } from "@/lib/google-maps-loader"
import { initializeAdminFrame } from "@/lib/admin-frame"

export type GoogleMapAddress = { formatted_address: string; geometry: { bounds?: unknown; viewport?: unknown; location?: unknown } }
export type GoogleMapViewport = {
  search(address: string): Promise<GoogleMapAddress[]>
  select(address: GoogleMapAddress): void
  capture(): Promise<string>
  dispose(): void
}

type FrameWindow = Window & {
  html2canvas?: (element: HTMLElement, options: Record<string, unknown>) => Promise<HTMLCanvasElement>
  MapSVGGoogleMapSvg?: { capture(element: HTMLElement, map: any, renderer: unknown): Promise<string> }
}

/** Only the retained Google viewport lives here; no legacy admin application is booted. */
export async function createGoogleMapViewport(
  iframe: HTMLIFrameElement,
  params: { signal: AbortSignal; onReady: (ready: boolean) => void; onError: (message: string) => void; onCloseRequest?: () => void },
): Promise<GoogleMapViewport> {
  const lifetime = new AbortController()
  let disposed = false
  let frame: FrameWindow | null = null
  let map: any = null
  let previousAuth: (() => void) | undefined
  let authFailure: (() => void) | undefined
  let authFailed = false
  let timer: ReturnType<typeof setTimeout> | undefined
  const abort = () => lifetime.abort(params.signal.reason)
  const dispose = () => {
    if (disposed) return
    disposed = true
    if (timer) clearTimeout(timer)
    params.signal.removeEventListener("abort", abort)
    lifetime.abort(new DOMException("Google Map closed.", "AbortError"))
    if (frame && map) frame.google?.maps?.event?.clearInstanceListeners(map)
    if (frame && frame.gm_authFailure === authFailure) frame.gm_authFailure = previousAuth
    // React removes this element. The adapter retires only its child document.
    iframe.removeAttribute("srcdoc")
    iframe.src = "about:blank"
    map = null
    frame = null
  }
  lifetime.signal.addEventListener("abort", dispose, { once: true })
  params.signal.addEventListener("abort", abort, { once: true })
  if (params.signal.aborted) abort()
  const active = () => {
    if (disposed || lifetime.signal.aborted) throw lifetime.signal.reason ?? new DOMException("Google Map closed.", "AbortError")
  }
  const bounded = async <T,>(promise: Promise<T>): Promise<T> => {
    active()
    let onAbort = () => {}
    try {
      return await Promise.race([promise, new Promise<never>((_, reject) => {
        onAbort = () => reject(lifetime.signal.reason)
        lifetime.signal.addEventListener("abort", onAbort, { once: true })
      })])
    } finally { lifetime.signal.removeEventListener("abort", onAbort) }
  }
  try {
    active()
    timer = setTimeout(() => lifetime.abort(new Error("The Google Map viewport took too long to load. Please try again.")), 35000)
    initializeAdminFrame(iframe)
    active()
    frame = iframe.contentWindow as FrameWindow | null
    const doc = iframe.contentDocument
    if (!frame || !doc) throw new Error("The Google Map frame is unavailable.")
    doc.body.style.overflow = "hidden"
    const viewport = doc.createElement("div")
    viewport.id = "mapsvg-google-map-fullscreen"
    viewport.style.cssText = "width:100%;height:100%;overflow:hidden"
    doc.body.replaceChildren(viewport)
    doc.addEventListener("keydown", (event) => {
      if (event.key === "Escape") { event.preventDefault(); params.onCloseRequest?.() }
    })
    previousAuth = frame.gm_authFailure
    authFailure = () => {
      authFailed = true
      if (!disposed) { params.onReady(false); params.onError("Google Maps API key is incorrect or is not authorized for this site.") }
      previousAuth?.()
      lifetime.abort(new Error("Google Maps API key is incorrect or is not authorized for this site."))
    }
    frame.gm_authFailure = authFailure
    await bounded(loadGoogleMapsApiOnce(frame, lifetime.signal))
    active()
    const api = frame.google.maps
    if (!api.Map) throw new Error("Google Maps API loaded without its map constructor.")
    const element = doc.getElementById("mapsvg-google-map-fullscreen")!
    map = new api.Map(element, {
      zoom: 2, center: new api.LatLng(-34.397, 150.644), mapTypeId: "roadmap",
      fullscreenControl: false, mapTypeControl: true, scaleControl: true,
      scrollwheel: true, streetViewControl: false, zoomControl: true,
    })
    let tilesReady = false
    let idle = false
    let initialReady!: () => void
    const initialViewport = new Promise<void>((resolve) => { initialReady = resolve })
    const ready = () => {
      if (disposed) return
      const usable = !authFailed && tilesReady && idle && Boolean(map.getBounds())
      params.onReady(usable)
      if (usable) initialReady()
    }
    api.event.addListener(map, "idle", () => { idle = true; ready() })
    api.event.addListener(map, "tilesloaded", () => { tilesReady = true; ready() })
    api.event.addListener(map, "bounds_changed", () => { idle = false; tilesReady = false; params.onReady(false) })
    api.event.addListener(map, "maptypeid_changed", () => { tilesReady = false; params.onReady(false) })
    const geocoder = new api.Geocoder()
    const bootstrap = getAdminParams()
    const pluginUrl = new URL(bootstrap.pluginUrl.replace(/\/?$/, "/"), document.baseURI)
    if (!bootstrap.pluginUrl || pluginUrl.origin !== window.location.origin) throw new Error("The Google Map screenshot assets are unavailable.")
    const asset = (path: string) => {
      const url = new URL(path, pluginUrl)
      if (bootstrap.version) url.searchParams.set("v", bootstrap.version)
      return url.href
    }
    const loadScript = (url: string) => bounded(new Promise<void>((resolve, reject) => {
      const script = doc.createElement("script")
      script.src = url
      script.onload = () => { script.onload = null; script.onerror = null; resolve() }
      script.onerror = () => { script.onload = null; script.onerror = null; reject(new Error("The Google Map screenshot assets could not load.")) }
      doc.head.appendChild(script)
    }))
    await Promise.all([
      loadScript(asset("js/vendor/html2canvas/html2canvas.min.js")),
      loadScript(asset("js/mapsvg-admin/shared/google-map-svg.js")),
    ])
    active()
    if (!frame.html2canvas || !frame.MapSVGGoogleMapSvg) throw new Error("The Google Map screenshot assets are unavailable.")
    await bounded(initialViewport)
    active()
    if (timer) clearTimeout(timer)
    return {
      async search(address) {
        active()
        return bounded(new Promise<GoogleMapAddress[]>((resolve, reject) => {
          geocoder.geocode({ address }, (results: GoogleMapAddress[] | null, status: string) => {
            if (status === "OK") resolve(results ?? [])
            else if (status === "ZERO_RESULTS") resolve([])
            else reject(new Error(`Address search failed (${status}).`))
          })
        }))
      },
      select(address) {
        active()
        const bounds = address.geometry.bounds ?? address.geometry.viewport
        if (bounds) map.fitBounds(bounds)
        else if (address.geometry.location) { map.setCenter(address.geometry.location); map.setZoom(14) }
      },
      async capture() {
        active()
        if (authFailed || !tilesReady || !idle) throw new Error("The Google Map viewport is not ready to download.")
        const result = await bounded(frame!.MapSVGGoogleMapSvg!.capture(element, map, frame!.html2canvas))
        active()
        return result
      },
      dispose,
    }
  } catch (failure) {
    dispose()
    throw failure
  }
}

/** Browser-only download: no file upload, saved Map creation or fixed server filename. */
export function downloadGoogleMapSvg(svg: string): void {
  const url = URL.createObjectURL(new Blob([svg], { type: "image/svg+xml;charset=utf-8" }))
  const link = document.createElement("a")
  link.href = url
  link.download = "mapsvg.svg"
  document.body.appendChild(link)
  try { link.click() } finally {
    link.remove()
    setTimeout(() => URL.revokeObjectURL(url), 1000)
  }
}
